\noindent For $1 \leq s \leq p$, let $\mc{J}(s)$ denote the set of all index subsets of $[p]$ of
size $s$.    

\begin{defn} For  $J \in \mc{J}(s)$, and $\alpha \in [1,\infty)$, define 
\begin{equation}\label{eq:lassocone}
\mc{C}(J, \alpha) = \{v \in {\mathbb R}^p:\, \nnorm{v_{J^c}}_1 \leq \alpha \nnorm{v_J}_1 \}. 
\end{equation}
\end{defn}

\begin{defn}\cite{CandesTao2005} Let $A \in {\mathbb R}^{N \times p}$ and $B_0(s;p) = \{v \in {\mathbb R}^p: \; \nnorm{v}_0 \leq s \}$. Define the $s$-sparse minimum and maximum eigenvalues associated with $A$ by 
\begin{equation*}
  \lambda_{\min}(s) = \min_{v \in B_0(s;p) \setminus \{0\}} \frac{\nnorm{A v}_2^2}{\nnorm{v}_2^2}, \qquad
  \lambda_{\max}(s) = \max_{v \in B_0(s;p) \setminus \{0\}} \frac{\nnorm{A v}_2^2}{\nnorm{v}_2^2}. 
\end{equation*}
Let $\delta \in (0,1)$. We say that $A$ is an ($s$, $\delta$)-\textbf{restricted isometry}  if
\begin{equation*}
  1 - \delta \leq \lambda_{\min}(s) \leq \lambda_{\max}(s) \leq 1+\delta.
\end{equation*}
\end{defn}

\begin{defn}\cite{Bickel2009} Let $A \in {\mathbb R}^{N \times p}$. We define the $(s, \alpha)$-\textbf{restricted eigenvalue} by 
\begin{equation}\label{eq:recondition}
\phi(s, \alpha) = \min_{J \in \mc{J}(s)} \, \min_{v \in \mc{C}(J, \alpha) \setminus
  0}\, \, \frac{\nnorm{A v}_2^2}{\nnorm{v_J}_2^2}. 
\end{equation}   
\end{defn}



\begin{lemma}\cite{Bickel2009} Suppose that $A$ is a ($3s, \delta^*/4$)-restricted isometry for some $\delta^* \in (0,1)$. The $(s, 3)$-restricted eigenvalue then satisfies $\phi(s, 3) \geq 1 - \delta^*$. 
\end{lemma}

\begin{lemma}\cite{Baraniuk2006}
Let $A$ be a random of matrix of size $N \times p$ satisfying 
\begin{equation}\label{eq:normpreservation}
 \p((1 - \epss) \nnorm{v}_2^2 \leq \nnorm{A v}_2^2 \leq (1 + \epss) \nnorm{v}_2^2) \leq 2 \exp(-N c_0(\epss))
\end{equation}
for any $\epss \in (0,1)$ and any $v \in {\mathbb R}^p$, where $c_0(\epss) > 0$ is a constant depending only on $\epss$. Then for any $\delta \in (0,1)$, there exist constants $c_1, c_2 > 0$ depending only on $\delta$ such that $A$ is a $(q, \delta)$-restricted isometry for any $q \leq c_1 N / \log(p/q)$ with probability at least $1 - 2 \exp(-c_2 N)$. 
\end{lemma}

\begin{lemma}\label{lem:DasGupta}(from Lemma 2.2 in \cite{DasGupta2003})
  Let $\pre$ denote the orthogonal projection on an $N$-dimensional subspace of ${\mathbb R}^p$ chosen uniformly at
  random from the Grassmannian $\textsf{G}(p, N)$. Then, for any $v \in {\mathbb R}^p$ and any $\epss \in (0,1)$,
  \begin{equation*}
    \p \left((1 - \epss) \nnorm{v}_2^2 \leq \frac{p}{N} \norm{\pre v}_2^2 \leq (1 + \epss) \nnorm{v}_2^2 \right) \leq 2 \exp(-N  (\epss^2/4 - \epss^3/6) \})
  \end{equation*}
\end{lemma}

