\section{Proof of Proposition \ref{prop:negative_result}}

Consider the least squares problem \eqref{eq:lsq} with $\y = \eps$:
\begin{equation*}
\min_{\Pi, \beta} \nnorm{\eps - \Pi X \beta}_2^2. 
\end{equation*} 
Omitting the term not depending on $\beta$, an equivalent problem is given by 
\begin{equation*}
\min_{\Pi, \beta} -2 \scp{\Pi \eps}{X \beta} + \nnorm{X \beta}_2^2. 
\end{equation*}
Re-parameterizing $X \beta = u \cdot r$, with $r \geq 0$ for $u \in \text{range}(X) \cap \mathbb{S}^{n-1}$, we obtain the optimization problem
\begin{equation*}
\min_{\Pi, u \in \text{range}(X) \cap \mathbb{S}^{n-1}, r \geq 0}  -2 \scp{\Pi \eps}{u} r + r^2. 
\end{equation*}
Observe that for any $u$ and $\Pi$, the optimal value of $r$ is found as 
\begin{equation*}
\wh{r}(u) = \max\{\scp{\Pi \eps}{u},0 \}. 
\end{equation*}
In particular, for a minimizer $(\wh{\Pi}, \wh{u})$,
\begin{equation*}
\wh{r} \coloneq \wh{r}(\wh{\Pi}, \wh{u}) = \nscp{\wh{\Pi} \eps}{\wh{u}}
\end{equation*}
so that $\wh{r} = \nnorm{X \wh{\beta}}_2$, and the optimal value of the objective is given by 
$-\wh{r}^2$. We hence have  
\begin{align*}
\wh{r} &= \max_{u \in \text{range}(X) \cap \mathbb{S}^{n-1}, \Pi} \nscp{\Pi \eps}{u} \\
       &\geq  \max_{1 \leq j \leq d, \Pi} \nscp{\Pi \eps}{X_j / \nnorm{X_j}_2} \\
       &\geq  \max_{\Pi} \nscp{\Pi \eps}{X_1} \frac{1}{\nnorm{X_1}_2}. 
\end{align*}
We now bound
\begin{equation*}
\max_{\Pi} \nscp{\Pi \eps}{X_1} \geq \nscp{\Pi_{\pm} \eps}{X_1},


\end{equation*}
where the permutation $\Pi_{\pm}$ is defined as follows. Define 
\begin{align*}
n_{\eps,+} = \{i:\; \epsilon_i > 0\}, \quad n_{\eps,-} = n - n_{\eps,+},  \quad n_{X_1,+} = \{i:\; X_{i1} > 0\}, \quad n_{X_1,-} = n - n_{X_1,+}.
\end{align*}
Let further 
\begin{equation}\label{eq:nplusnminus}
n_+ = \min\{n_{\eps,+},  n_{X_1,+} \},  \quad n_- = \min\{n_{\eps,-},  n_{X_1,-} \}, \quad 
n_{\pm} = n - n_+ - n_-. 
\end{equation}


Denote by 
\begin{alignat*}{2}
&i_1^+ < \ldots < i_{n_{X,+}}^+ \quad &&\text{the indices of the positive entries of $X_1$},\\
&j_1^+ < \ldots < j_{n_{\eps,+}}^+ \quad &&\text{the indices of the positive entries of $\eps$},\\
&i_1^- < \ldots < i_{n_{X,-}}^- \quad &&\text{the indices of the negative entries of $X_1$},\\
&j_1^- < \ldots < j_{n_{\eps,-}}^- \quad &&\text{the indices of the negative entries of $\eps$}.
\end{alignat*}
Furthermore, let 
\begin{align*}
&i_{1}^{\pm} < \ldots < i_{n_{\pm}}^{\pm} \\
&j_{1}^{\pm} < \ldots < j_{n_{\pm}}^{\pm} 
\end{align*}
be the indices in 
\begin{align*}
                    & \{1,\ldots,n\} \setminus (\{i_1^+,\ldots, i_{n_+}^+\} \cup \{i_1^-,\ldots, i_{n_-}^-\}) \\
\text{respectively}\;\, & \{1,\ldots,n\} \setminus (\{j_1^+,\ldots, j_{n_+}^+\} \cup \{j_1^-,\ldots, j_{n_-}^-\})
\end{align*}
in increasing order. We then construct $\Pi_{\pm}$ such that 
\begin{equation*}
\nscp{\Pi_{\pm} \eps}{X_1} = \sum_{k = 1}^{n_+} X_{1{i_k^+}} \epsilon_{j_k^+} + 
\sum_{k = 1}^{n_-} X_{1{i_k^-}} \epsilon_{j_k^-} + \sum_{k = 1}^{n_{\pm}} X_{1{i_k}^{\pm}} \; \epsilon_{{j_k}^{\pm}}. 
\end{equation*}
All terms inside the first two sums are i.i.d.~from the same distribution as $|g| |h|$, where $g$ and $h$ are independent
$N(0,1)$-random variables, and accordingly the terms inside the last summand are i.i.d.~from the same distribution as
$-|g||h|$. Conditional on $n_{\pm}$,  hence $\nscp{\Pi_{\pm} \eps}{X_1}$ follows the same distribution as 
\begin{equation*}
\sum_{i = 1}^{n - n_{\pm}} |g_i| |h_i|  - \sum_{i=n - n_{\pm} + 1}^{n} |g_i| |h_i|,
\end{equation*}
where $\{ g_i \}_{i = 1}^n$ and $\{ h_i \}_{i = 1}^n$ are two independent sequences of $n$ i.i.d.~random variables from the $N(0,1)$-distribution. The expectation of the above expression (conditional on $n_{\pm}$)
is given by 
\begin{equation*}
(n - 2 n_{\pm}) \E[|g||h|] = (n - 2 n_{\pm}) \E[|g|]^2 = (n - 2 n_{\pm}) \frac{2}{\pi}. 
\end{equation*}
From Proposition 5.16 in \cite{Vershynin2010}, we have the following concentration inequality: 
\begin{equation*}  
\p \left(\left|\sum_{i = 1}^{n - n_{\pm}} (|g_i| |h_i| - \E[|g||h|]) - \sum_{i=n - n_{\pm} + 1}^{n} (|g_i| |h_i| - \E[|g||h|]) \right| \geq 
(n - 2 n_{\pm}) \frac{1}{\pi} \Big| n_{\pm} \right) \leq \exp(-n c).
\end{equation*}
Hence, conditional on $n_{\pm}$, with probability at least $1 - \exp(-nc)$, 
\begin{equation*}
\sum_{i = 1}^{n - n_{\pm}} |g_i| |h_i|  - \sum_{i=n - n_{\pm} + 1}^{n} |g_i| |h_i|  \geq \frac{1}{\pi} (n - 2 n_{\pm}). 
\end{equation*}
Consider the definition of $n_+$ and $n_-$ Observe that $n_{\eps, +}$, $n_{X_1, +}$, $n_{\eps, -}$ and $n_{X_1, -}$ are each binomial random variables with $n$ trials and probability of success $1/2$. By repeated application of Hoeffding's inequality, we hence have 
\begin{equation*} 
\p(n_{+} \leq 3n/8) \leq 2\exp(-n/32), \quad \p(n_{-} \leq 3n/8) \leq 2 \exp(-n/32).
\end{equation*}
Conditional on the events $\{ n_{+} > 3n/8\}$ and $\{ n_{-} > 3n/8\}$, we have $n_{\pm} \leq 1/4$ and thus with probability at least $1 - C \exp(-nc)$
\begin{equation*}
\sum_{i = 1}^{n - n_{\pm}} |g_i| |h_i|  - \sum_{i=n - n_{\pm} + 1}^{n} |g_i| |h_i|  \geq \frac{n}{2\pi} . 
\end{equation*}
Accordingly, the same applies to the event $\{ \nscp{\Pi_{\pm} \eps}{X_1} > \frac{n}{2\pi} \}$. 
Lemma \ref{lem:normconcentration} in Appendix \ref{app:aux} yields $\nnorm{X_1}_2 \leq 2 \sqrt{n}$ with probability at least $1 - \exp(-n/2)$. Putting together the pieces, it follows that with probability at least $1 - C \exp(-nc)$
\begin{equation*}
\nnorm{X \wh{\beta}}_2 = \wh{r} \geq \frac{\sqrt{n}}{4\pi} \quad \Rightarrow \; \nnorm{\wh{\beta}}_2 \geq  \frac{\sqrt{n}}{\sigma_{\max}(X) 4\pi},
\end{equation*}   
where $\sigma_{\max}(X)$ denotes the maximum singular value of $X$. Finally, Lemma \ref{lem:extremesingularvalues} in Appendix \ref{app:aux} yields that $\sigma_{\max}(X) \leq \sqrt{2n} + \sqrt{d}$ with probability at least $1 - \exp(-c n)$, which concludes the proof. 


\section{Proof of Theorem \ref{theo:constrained_permutation}}\label{app:theo:constrained_permutation}

We start with a basic, yet important observation that allows us to decouple $\wh{\Pi}$ and $\wh{\beta}$. Let
$\pr_X$ and $\pr_X^{\perp}$ denote the orthogonal projection on $\text{range}(X)$ respectively its orthogonal complement.


\begin{lemma}\label{lem:decoupling} Consider optimization problem \eqref{eq:lsq}. Then, if $n \geq  d$, with probability one 
\begin{equation}\label{eq:decomposition}  
  \wh{\Pi}^{\T} \in \argmin_{\Pi \in \mc{P}_{n,k}} \nnorm{\pre_X^{\perp} \Pi \mathbf{y}}_2^2, \qquad \wh{\beta} \in \left\{ \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \wh{\Pi}^{\T} \y}{n},
  \; \, \wh{\Pi}^{\T} \in \argmin_{\Pi \in \mc{P}_{n,k}} \nnorm{\pre_X^{\perp} \Pi \mathbf{y}}_2^2 \right \}.  
\end{equation}
\end{lemma}

\begin{proof} We have 
\begin{align*}
  \min_{\Pi, \beta} \|\Pi X\beta-\y\|_2^2 &= \min_{\Pi, \beta} \|X\beta-\Pi \y\|_2^2  \\
                                        &=  \min_{\Pi, \beta} \left\{ \|\pr_X^{\perp} \Pi \y\|_2^2   +  \|X\beta- \pr_X \Pi \y\|_2^2 \right\}. 
\end{align*}
The second part can always be made equal to zero by choosing $\beta$ such that $X \beta = \pr_X \Pi \y$. It hence suffices to
minimize the first part w.r.t.~$\Pi$ and to back-substitute the result into the second part. Under model (\text{\textbf{G}}), $X$ is
non-singular with probability one as long as $n \geq d$ which yields the second expression in \eqref{eq:decomposition}. 
\end{proof}
\noindent In the next lemma, we bound the $\ell_2$-distance between $\Pi^{*\T} \y$ and $\wh{\Pi}^{\T} \y$. 
\begin{lemma}\label{lem:bound_pi} Under the conditions of Theorem \ref{theo:constrained_permutation}, the following holds
  with probability at least $1 - \frac{7}{2} \exp \left(-\frac{\psi(\epss, d/n) \nu_n^2}{8} \right) - \exp(-\{ w(\mc{T}) \vee \log n\})$,
  where $\psi(\epss, d/n)$ is defined in \eqref{eq:lowerbound} below. 
\begin{equation*} 
\nnorm{\wh{\Pi}^{\T} \y - \Pi^{*\T} \y}_2 \leq  \frac{2 (1 + \sqrt{2})\sigma \epss^{-2} \{w(\mc{T}) \vee \log n\}}{\sqrt{n}}.
\end{equation*}
\end{lemma}
\begin{proof} In view of Lemma \ref{lem:decoupling}, by definition of $\wh{\Pi}^{\T}$ and the fact that $\Pi^{*\T}$ is a feasible solution, we have
 \begin{align*} 
&\nnorm{\pr_X^{\perp}\wh{\Pi}^{\T} \y}_2^2  \leq  \nnorm{\pr_X^{\perp}\Pi^{*\T} \y}_2^2 \\
  \Rightarrow \quad & \nnorm{\pr_X^{\perp}(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y + \pr_X^{\perp}\Pi^{*\T} \y }_2^2 \leq \nnorm{\pr_X^{\perp}\Pi^{*\T} \y}_2^2 \\
  \Rightarrow \quad  & \nnorm{\pr_X^{\perp}(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2^2 \leq 2 |\nscp{\pr_X^{\perp}\Pi^{*\T} \y}{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}|. 
 \end{align*}
Since
\begin{equation*}
\pr_X^{\perp} \Pi^{*\T} \y = \pr_X^{\perp} (X \beta^* + \eps) = \pr_X^{\perp}\eps,
\end{equation*}
we have the implication that
\begin{equation*}
  \nnorm{\pr_X^{\perp}(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2^2 \leq 2 |\nscp{\pr_X^{\perp}\eps}{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}|.
\end{equation*}
Dividing both sides by $\nnorm{\pr_X^{\perp}(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2$, we obtain that
\begin{align}
  &\nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2^2 \nnorm{\pr_X^{\perp} \wh{\Delta}}_2^2 \leq 2 |\nscp{\pr_X^{\perp}\eps}{\wh{\Delta}}| \nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2, \qquad \wh{\Delta} \coloneq
  \frac{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}{\nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2} \notag \\
\Rightarrow \quad &\nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2  \nnorm{\pr_X^{\perp}\wh{\Delta}}_2^2  \leq 2 |\nscp{\pr_X^{\perp}\eps}{\wh{\Delta}}| \label{eq:Pi_apply_Gordon}.  
\end{align}
\emph{i) Lower bounding the left hand side of \eqref{eq:Pi_apply_Gordon}.}\\
Observe that $\wh{\Delta} \in \mc{T}$ as defined in \eqref{eq:setT}. Moreover, note that under (\text{\textbf{G}}), the random subspace
$\text{range}(X) \subseteq {\mathbb R}^n$ follows the uniform distribution on the Grassmannian $\textsf{G}(n,d)$. Hence, applying Lemma \ref{lem:escape} with $K = \mc{T}$,
$V = \text{range}(X)$ and thus $m = n$ and $l = n-d$, we have for any $\epss \in (0,1/2)$ in compliance with \eqref{eq:cond_samples_unrelaxed}    
\begin{align}\label{eq:lowerbound}
  \begin{split}
   \p(\text{dist}(\mc{T}, \text{range}(X)) > \epss)
   &= \p \left(\min_{\Delta \in \mc{T}} \nnorm{\pr_X^{\perp} \Delta}_2 > \epss \right) \\
   &\geq 1 - \frac{7}{2} \exp \left(-\frac{1}{2} \left( \frac{(1 - \epss)\nu_{n-d} - \epss \nu_n  - w(\mc{T})}{3 + \epss + \epss \nu_n / \nu_{n-d}} \right)^2 \right) \\
   &\geq 1 - \frac{7}{2} \exp \left(-\frac{\psi(\epss, d/n) \nu_n^2}{8} \right), \quad
   \psi(\epss, d/n) \coloneq \left( \frac{(1- \epss) \frac{\nu_{n-d}}{\nu_n} - \epss}{3 + \epss + \frac{\epss^2}{1-\epss}} \right)^2,
 \end{split}
\end{align}
where the last inequality follows from condition \eqref{eq:cond_samples_unrelaxed}. Conditional on the event $\{ \nnorm{\pr_X^{\perp} \Delta}_2 \geq \epss \}$, which holds with the probability as stated, the left hand side of \eqref{eq:Pi_apply_Gordon} is lower bounded by $\epss^2 \nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2$.  
\vskip1ex
\noindent \emph{ii) Upper bounding the right hand side of \eqref{eq:Pi_apply_Gordon}.}\\
Consider $t > 0$ arbitrary, to be chosen later.  We have
\begin{align*}
\p(|\nscp{\pr_X^{\perp}\eps}{\wh{\Delta}}| \geq t) \leq \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > t \right). 
\end{align*}
\noindent Now note that $\eps$ and $\pr_X^{\perp}$ are independent. As a result, when conditioning on $\pr_X^{\perp}$, we have from Lemma \ref{lem:concentration_width}
that
\begin{align*}
  \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > t \;\;\Big| \pr_X^{\perp} \right) &\leq
  \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > \E\left[\sup_{\Delta \in \mc{T}}  |\nscp{\pr_X^{\perp}\eps}{\Delta}| \;\; \Big|  \pr_X^{\perp} \right] +  \tau \;\;\Big| \pr_X^{\perp} \right) \\
                                                                                                           &\leq \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > \sigma  w(\mc{T})  +  \tau \;\;\Big| \pr_X^{\perp} \right) \\
                                                                                                           &\leq \exp(-\tau^2 / (2 \sigma^2)),
                                                                                                             \quad \tau \coloneq t - \E\left[\sup_{\Delta \in \mc{T}}  |\nscp{\pr_X^{\perp}\eps}{\Delta}| \;\; \Big|  \pr_X^{\perp} \right] \\
&\qquad \qquad \qquad \qquad \qquad \;\; \geq  t - \sigma w(\mc{T}). 
\end{align*}
The second equality is a consequence of the Sudakov-Fernique comparison inequality (Theorem 2.2.3 in \cite{AdlerTaylor2007}) and the fact that
$\nnorm{\pr_X^{\perp}}_2 \leq 1$. Choosing $t = (1 + \sqrt{2}) \sigma \{w(\mc{T}) \vee \log n \}$, combining this result with i), and putting together the pieces in \eqref{eq:Pi_apply_Gordon}, the assertion of the lemma follows.   
\end{proof}
\noindent In order to complete the proof of Theorem \ref{theo:constrained_permutation}, we need one last lemma whose proof is deferred to Appendix \ref{app:Xteps}.

\begin{lemma}\label{lem:Xteps} Let $\sigma_{\min}(\cdot)$ denote the minimum singular value of a matrix. If $n \geq 9 \vee 4d$, it holds that
\begin{align*}
  &\p \left( \left \{\sigma_{\min}(X / \sqrt{n}) < 1 - \sqrt{\frac{4 d \vee \log n}{n}} \right \}   \cup \left\{ \norm{ \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \eps}{\sqrt{n}}}_2 \geq \sigma \frac{\sqrt{5 (d \vee \log n)} \}}{1 - \sqrt{\frac{4 d \vee \log n}{n}}} \right \} \right)\\
  &\leq 2 \exp \left(-\frac{1}{2} (d \vee \log n) \right).  
\end{align*}
\end{lemma}
\noindent Equipped with Lemmas \ref{lem:bound_pi} and \ref{lem:Xteps}, we are in position to conclude
Theorem \ref{theo:constrained_permutation}. Expanding the expression for $\wh{\beta}$ in \eqref{eq:decomposition}, we obtain that
\begin{align*}
  \wh{\beta} = \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \wh{\Pi}^{\T} \y}{n} 
  &= \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \Pi^{*\T} \y}{n} + \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} (\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}{n} \\
  &= \beta^* + \left( \frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} (\eps + (\wh{\Pi}^{\T} - \Pi^{*\T}) \y)}{n},  
\end{align*}
and thus
\begin{align*}
  \nnorm{\wh{\beta} - \beta^*}_2 &\leq  \frac{\norm{ \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \eps}{\sqrt{n}}}_2}{\sqrt{n}} + \frac{\norm{\left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T}}{\sqrt{n}}}_2 \nnorm{(\wh{\Pi}^{\T} - \Pi^{*\T}) \y}_2}{\sqrt{n}} \\
                                 &\leq \frac{\norm{ \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \eps}{\sqrt{n}}}_2}{\sqrt{n}} + \frac{\frac{1}{\sigma_{\min}(X / \sqrt{n})}\nnorm{(\wh{\Pi}^{\T} - \Pi^{*\T}) \y}_2}{\sqrt{n}} \\
&\leq \frac{\sigma}{1 - \sqrt{\frac{4 d \vee \log n}{n}}} \left(\sqrt{\frac{5 (d \vee \log n)}{n}} + \frac{2 (1 + \sqrt{2})\sigma \epss^{-2} \{w(\mc{T}) \vee \log n\}}{\sqrt{n}} \right)                                   
\end{align*}
with the stated probability by combining Lemmas \ref{lem:bound_pi} and \ref{lem:Xteps}.   



\section{Proof of Corollary \ref{corro:refitting}}

Observe that the event $\{\wh{S} = S^* \}$ is implied by the event
\begin{equation*}
\left\{ \min_{i \in S^*} |y_i - y_{\varphi^{-1}(i)}| > \nnorm{\Pi^{*\T} \y - \wh{\Pi}^{\T} \y}_{\infty} \right \},  
\end{equation*}
which is in turn implied by
\begin{equation*}
\left\{ \min_{i \in S^*} |y_i - y_{\varphi^{-1}(i)}| > \nnorm{\Pi^{*\T} \y - \wh{\Pi}^{\T} \y}_{2} \invcoloneq \gamma \right\},  
\end{equation*} 
We now have 
\begin{align*}
\p\left(\min_{i \in S^*} |y_i - y_{\varphi^{-1}(i)}| \leq \gamma \right) 
&\leq \sum_{i \in S^*} \p\left(|y_i - y_{\varphi^{-1}(i)}| \leq \gamma \right) \\
&\leq k  \max_{i \neq j} \p\left(|y_i - y_{j}| \leq \gamma \right).
\end{align*}
Note that for any $i \neq j$, $y_i - y_j \sim N(0, 2 (\nnorm{\beta^*}_2^2 + \sigma^2))$. Invoking 
Lemma \ref{lem:smallball}, we thus obtain that for any $i \neq j$ 
\begin{equation*}  
\p\left(|y_i - y_{j}| \leq \gamma \right) \leq \frac{\gamma}{\sqrt{2 (\nnorm{\beta^*}_2^2 + \sigma^2)}}.
\end{equation*}
It hence follows from the previous two displays that for any $\delta > 0$, 
\begin{equation*}
\p\left(\min_{i \in S^*} |y_i - y_{\varphi^{-1}(i)}| \leq \gamma \right) \leq \delta
\end{equation*}
if 
\begin{equation*}
\nnorm{\beta^*}_2^2 > \frac{k^2 \gamma^2}{2 \delta^2}. 
\end{equation*}
Substituting $\gamma$ by the bound from Lemma \ref{lem:bound_pi}, the above condition becomes
\begin{equation*}
\text{SNR} > \frac{2 (1 + \sqrt{2})^2 \epss^{-4}}{\delta^2}\,\cdot \frac{k^2  \{w(\mc{T}) \vee \log n\}^2}{n },
\end{equation*}    
and the first part of the corollary follows from Lemma \ref{lem:bound_pi}. Turning to the second part, consider
the least squares estimator using the reduced data set $\{(\x_i, y_i), \; i \in [n] \setminus S^* \}$ and denote
by $\wh{\beta}(S^*)$ the corresponding least squares estimator. We then have for any $\delta > 0$ 
\begin{equation*}
\p(\nnorm{\wh{\beta}(S^*) - \beta^*}_2 \leq \delta) = \p(\nnorm{\wh{\beta}(S^*) - \beta^*}_2 \leq \delta, \wh{S} = S^*) + 
\p(\nnorm{\wh{\beta}(S^*) - \beta^*}_2 \leq \delta, \wh{S} \neq S^*),
\end{equation*} 
which implies 
\begin{equation*}
\p(\nnorm{\wh{\wh{\beta}} - \beta^*}_2 \leq \delta) \geq \p(\nnorm{\wh{\beta}(S^*) - \beta^*}_2 \leq \delta) - \p(\wh{S} \neq S^*). 
\end{equation*}
It thus remains to control the first probability on the left hand side, which can be done with arguments similar 
to those used in the last part of the proof of Theorem \ref{theo:constrained_permutation}.




\section{Proof of Theorem \ref{theo:relaxation}}\label{app:theo:relaxation}

We start with a Lemma that parallels Lemma \ref{lem:decoupling}. The reasoning is analogous, and the proof is hence omitted.   
\begin{lemma}\label{lem:decoupling_LAD} 
Consider optimization problem \eqref{eq:relax_2} with solution $(\wt{\beta}, \wt{e})$. Then, if $n \geq d$, with probability one
\begin{align*}
  \wt{e} \in \argmin_{e} \frac{1}{n} \nnorm{\pre_X^{\perp} (\y - \sqrt{n}  e)}_2^2 + \lambda \nnorm{e}_1, \quad
  \wt{\beta} \in \Bigg\{ &\left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} (\y - \sqrt{n} \wt{e})}{n}, \\
  &\wt{e} \in \argmin_{e} \frac{1}{n} \nnorm{\pre_X^{\perp} (\y - \sqrt{n} e)}_2^2 + \lambda \nnorm{e}_1 \Big \}.
\end{align*}
\end{lemma}
\noindent For our analysis of the optimization problem of Lemma \ref{lem:decoupling_LAD}, we need the following
crucial lemma whose proof is provided in Appendix \ref{app:lem:RE}.  
\begin{lemma}\label{lem:RE} There exists constants $c_1, c_2, \epss > 0$ so that
  if $k \leq c_1 \frac{n-d}{\log(n/k)}$, the following event holds with probability at least $1 - 2 \exp(-c_2 (n-d) )$. 
\begin{equation*}
  \left\{ \frac{1}{n} \nnorm{\pre_X^{\perp} v}_2^2 \geq \epss \frac{n-d}{n} \nnorm{v}_2^2, \quad v \in \mc{C}(S^*, 3)
  \right \},
\end{equation*}
with $S^* = \{j:\;\Pi_{jj}^* \neq 1 \}$ and $\mc{C}(S^*, 3)$ defined in \eqref{eq:lassocone}. 
\end{lemma}
\noindent In correspondence with Lemma \ref{lem:bound_pi}, we first bound $\nnorm{\wt{e} - e^*}_2$,
where $e^* = (\Pi^* X \beta^* - X \beta^*)/\sqrt{n}$.
\begin{lemma}\label{lem:bound_e} Under the conditions of Theorem \ref{theo:relaxation}, with probability at least $1 - 2 \exp(-c_{\epss} (n-d))  - 2n^{-M^2}$, we have 
\begin{equation*}
\nnorm{\wt{e} - e^*}_2 \leq   48 (1 + M) \sigma  \frac{n}{n-d} \epss^{-1} \sqrt{\frac{k \log n}{n}}.  
\end{equation*}
\end{lemma}
\begin{proof} We first decompose
\begin{equation*}
  \pr_X^{\perp} \y = \pr_X^{\perp} (X \beta^* + \sqrt{n} e^* + \eps) = \pr_X^{\perp} \sqrt{n} e^*  + \wt{\eps}, \quad
  \wt{\eps} \coloneq \pr_X^{\perp} \eps.  
\end{equation*}
According to Lemma \ref{lem:decoupling_LAD}, since $\wt{e}$ is a minimizer, we have that
\begin{equation*}
  \frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e}) + \wt{\eps}}_2^2 + \lambda \nnorm{\wt{e}}_1 \leq
  \frac{1}{n} \nnorm{\wt{\eps}}_2^2  + \lambda \nnorm{e^*}_1. 
\end{equation*}
Expanding the square on the left-hand side and re-arranging terms, we obtain that
\begin{equation}\label{eq:lasso_basic}
\frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 + \lambda \nnorm{\wt{e}}_1 \leq 2 |\scp{e^* - \wt{e}}{\wt{\eps}/\sqrt{n}}| + \lambda \nnorm{e^*}_1, 
\end{equation}
which implies
\begin{equation*}
 \lambda \nnorm{\wt{e}}_1 \leq 2 \nnorm{e^* - \wt{e}}_{1} \nnorm{\wt{\eps}/\sqrt{n}}_{\infty} + \lambda \nnorm{e^*}_1,
\end{equation*}
and in turn
\begin{align*}
  \lambda \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 = \lambda \nnorm{\wt{e}_{(S^*)^c}}_1 &\leq 2 \nnorm{e^* - \wt{e}}_{1} \nnorm{\wt{\eps}/\sqrt{n}}_{\infty} + \lambda (\nnorm{e^*}_1 - \nnorm{\wt{e}_{S^*}}_1) \\
  &\leq  2 \nnorm{e^* - \wt{e}}_{1} \underbrace{\nnorm{\wt{\eps}/\sqrt{n}}_{\infty}}_{\invcoloneq \lambda_0} + \lambda \nnorm{e_{S^*}^*- \wt{e}_{S^*}}_1. 
\end{align*}
Re-arranging, we arrive at 
\begin{equation*}
(\lambda - 2\lambda_0) \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 \leq (\lambda + 2 \lambda_0) \nnorm{e_{S^*}^*- \wt{e}_{S^*}}_1. 
\end{equation*}
Conditional on the event $\Lambda =\{\lambda \geq 4 \lambda_0 \}$, we hence have that
\begin{equation}\label{eq:cone_condition}
  \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 \leq 3 \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_1.
\end{equation}
\noindent Equipped with this is intermediate result, we go back to \eqref{eq:lasso_basic}. We first
obtain by re-arranging that 
\begin{align*}
  \frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 &\leq (2 \lambda_0 + \lambda) \nnorm{\wt{e} - e^*}_1 \\
  &\leq (2 \lambda_0 + \lambda) 4 \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_1 \\
  &\leq (2 \lambda_0 + \lambda) 4 \sqrt{k} \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_2, 
\end{align*}
where we have used \eqref{eq:cone_condition} in the second inequality.  
In order to lower bound the left hand side, note that \eqref{eq:cone_condition} can be written as
$\wt{e} - e^* \in \mc{C}(S^*, 3)$ according to \eqref{eq:lassocone}. Conditional on the event in Lemma
\ref{lem:RE},
\begin{equation*}
\frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 \geq  \epss \frac{n-d}{n}  \nnorm{e^* - \wt{e}}_2^2.
\end{equation*}
Combining this with the previous display, we find that
\begin{equation*}
 \nnorm{e^* - \wt{e}}_2 \leq 12  \epss^{-1} \frac{n}{n-d} \lambda \sqrt{k}. 
\end{equation*}
\noindent In view of Lemma \ref{lem:maximalgaussian}, the choice $\lambda = 4 (1 + M) \sigma \sqrt{2 \log(n) / n}$ for $M \geq 0$
guarantees that the event $\Lambda$ defined above \eqref{eq:cone_condition} occurs with probability at least $1 - 2n^{-M^2}$.
This completes the proof of the Lemma. 
\end{proof}
\noindent Using Lemmas \ref{lem:bound_pi} and \ref{lem:decoupling_LAD}, the proof of the theorem is completed along the lines
of the last part of the proof of Theorem \ref{theo:constrained_permutation}. For brevity, we omit those steps here.

\section{Proof of Theorem \ref{theo:permutationrecovery}}


The proof of part (a) of the theorem relies on two lemmas, which are stated and proved first. 
\begin{lemma}\label{lem:up}
Let $\gamma, \delta > 0$. Consider the event 
\begin{equation}\label{eq:Agamma}
\mathcal{A}_{\gamma}= \left\{\min_{i<j}(\x_i^\top\beta^*-\x_j^\top\beta^*)^2\le \gamma^2 \right\}.
\end{equation}
Then $\p\left( \mathcal{A}_{\gamma}\right)< \delta$ if 
\[
\nnorm{\beta^*}_2^2>\dfrac{n^2(n-1)^2}{4\delta^2\pi}\gamma^2.
\]
